describe('InvoiceListComponent', () => {
  let fixture: ComponentFixture<InvoiceListComponent>;

  beforeEach(() => {
    TestBed.configureTestingModule({ imports: [InvoiceListComponent] });
    fixture = TestBed.createComponent(InvoiceListComponent);
    fixture.componentRef.setInput('invoices', [{ id: 'F-1', amount: 120 }]);
    fixture.detectChanges();
  });

  it('expose un aria-label accessible par ligne', () => {
    const row = fixture.nativeElement.querySelector('tr[role="row"]');
    expect(row.getAttribute('aria-label')).toContain('Facture F-1');
  });
});

